func worker(jobs <-chan int, results chan<- int, wg *sync.WaitGroup) {
	defer wg.Done()
	for n := range jobs { // ends when jobs is closed & drained
		results <- n * n
	}
}

func main() {
	jobs, results := make(chan int), make(chan int)
	var wg sync.WaitGroup
	for id := 1; id <= 3; id++ { // fixed pool of 3
		wg.Add(1)
		go worker(jobs, results, &wg)
	}
	go func() { // producer: send all jobs, then close
		for n := 1; n <= 5; n++ {
			jobs <- n
		}
		close(jobs)
	}()
	go func() { wg.Wait(); close(results) }() // close once, after all done
	sum := 0
	for r := range results {
		sum += r
	}
	fmt.Println(sum) // 1+4+9+16+25 = 55
}
